import test from 'node:test';
import assert from 'node:assert';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents', async (t) => {
  await t.test('rounds 124.5 to 124 (banker\'s rounding, even)', () => {
    assert.strictEqual(roundCents(124.5), 124);
  });

  await t.test('rounds 125.5 to 126 (banker\'s rounding, odd)', () => {
    assert.strictEqual(roundCents(125.5), 126);
  });

  await t.test('rounds 2.4 down to 2', () => {
    assert.strictEqual(roundCents(2.4), 2);
  });

  await t.test('rounds -0.5 to 0', () => {
    assert.strictEqual(roundCents(-0.5), 0);
  });
});

test('formatEuros', async (t) => {
  await t.test('formats positive amount with euro symbol', () => {
    assert.strictEqual(formatEuros(123456), '€1,234.56');
  });

  await t.test('formats negative amount with minus sign', () => {
    assert.strictEqual(formatEuros(-5), '-€0.05');
  });

  await t.test('formats zero', () => {
    assert.strictEqual(formatEuros(0), '€0.00');
  });

  await t.test('formats amount with thousands separator', () => {
    assert.strictEqual(formatEuros(1234567), '€12,345.67');
  });
});

test('parseEuros', async (t) => {
  await t.test('parses integer', () => {
    const result = parseEuros('12');
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value, 1200);
  });

  await t.test('parses decimal with one digit', () => {
    const result = parseEuros('12.5');
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value, 1250);
  });

  await t.test('parses decimal with two digits', () => {
    const result = parseEuros('1,234.56');
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value, 123456);
  });

  await t.test('rejects invalid format', () => {
    const result = parseEuros('abc');
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'AMOUNT_INVALID');
  });
});

test('RATES', async (t) => {
  await t.test('defines EUR, USD, GBP rates', () => {
    assert.strictEqual(RATES.EUR, 1);
    assert.strictEqual(RATES.USD, 1.085);
    assert.strictEqual(RATES.GBP, 0.8425);
  });
});

test('convert', async (t) => {
  await t.test('converts EUR to itself (rate 1)', () => {
    const result = convert(10000, 'EUR');
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value, 10000);
  });

  await t.test('converts EUR to USD (rate 1.085)', () => {
    const result = convert(10000, 'USD');
    assert.strictEqual(result.ok, true);
    // 10000 * 1.085 = 10850
    assert.strictEqual(result.value, 10850);
  });

  await t.test('converts EUR to GBP (rate 0.8425)', () => {
    const result = convert(10000, 'GBP');
    assert.strictEqual(result.ok, true);
    // 10000 * 0.8425 = 8425
    assert.strictEqual(result.value, 8425);
  });

  await t.test('returns UNKNOWN_CURRENCY for invalid currency', () => {
    const result = convert(10000, 'JPY');
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'UNKNOWN_CURRENCY');
  });

  await t.test('rounds result to nearest cent', () => {
    const result = convert(1, 'USD');
    assert.strictEqual(result.ok, true);
    // 1 * 1.085 = 1.085, rounds to 1
    assert.strictEqual(result.value, 1);
  });

  await t.test('converts zero', () => {
    const result = convert(0, 'USD');
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value, 0);
  });

  await t.test('converts negative amount', () => {
    const result = convert(-10000, 'USD');
    assert.strictEqual(result.ok, true);
    assert.strictEqual(result.value, -10850);
  });

  await t.test('handles rounding edge case', () => {
    // Test a value that requires rounding
    const result = convert(923, 'GBP');
    assert.strictEqual(result.ok, true);
    // 923 * 0.8425 = 777.6175, rounds to 778
    assert.strictEqual(result.value, 778);
  });

  await t.test('case-sensitive currency codes', () => {
    const result = convert(10000, 'usd');
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'UNKNOWN_CURRENCY');
  });
});

test('formatMoney', async (t) => {
  await t.test('formats EUR with euro symbol', () => {
    assert.strictEqual(formatMoney(123456, 'EUR'), '€1,234.56');
  });

  await t.test('formats USD with dollar symbol', () => {
    const result = formatMoney(100000, 'USD');
    assert.match(result, /^\$/);
    assert.match(result, /1,085\.00$/);
  });

  await t.test('formats GBP with pound symbol', () => {
    const result = formatMoney(100000, 'GBP');
    assert.match(result, /^£/);
    assert.match(result, /842\.50$/);
  });

  await t.test('formats negative USD amount', () => {
    assert.strictEqual(formatMoney(-10000, 'USD'), '-$108.50');
  });

  await t.test('formats zero in different currencies', () => {
    assert.strictEqual(formatMoney(0, 'EUR'), '€0.00');
    assert.strictEqual(formatMoney(0, 'USD'), '$0.00');
    assert.strictEqual(formatMoney(0, 'GBP'), '£0.00');
  });

  await t.test('formats small amount (1 cent EUR to USD)', () => {
    const result = formatMoney(1, 'USD');
    assert.match(result, /\$0\.01/);
  });

  await t.test('formats large amount with thousands separator', () => {
    const result = formatMoney(123456789, 'USD');
    assert.match(result, /\$1,340,231\.69/);
  });

  await t.test('handles unknown currency gracefully', () => {
    const result = formatMoney(10000, 'JPY');
    assert.strictEqual(result, 'Unknown currency');
  });

  await t.test('formats USD properly', () => {
    // 10000 EUR cents = €100
    // €100 * 1.085 = $108.50
    assert.strictEqual(formatMoney(10000, 'USD'), '$108.50');
  });

  await t.test('formats GBP properly', () => {
    // 10000 EUR cents = €100
    // €100 * 0.8425 = £84.25
    assert.strictEqual(formatMoney(10000, 'GBP'), '£84.25');
  });

  await t.test('formats with correct decimal places', () => {
    // 123 EUR cents
    const result = formatMoney(123, 'USD');
    // 123 * 1.085 = 133.455, rounds to 133
    assert.match(result, /\$1\.33/);
  });
});

